// And groups predicates with the AND operator between them.
func And(predicates ...predicate.BundleUserEntitlements) predicate.BundleUserEntitlements {
	return predicate.BundleUserEntitlements(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.BundleUserEntitlements) predicate.BundleUserEntitlements {
	return predicate.BundleUserEntitlements(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.BundleUserEntitlements) predicate.BundleUserEntitlements {
	return predicate.BundleUserEntitlements(sql.NotPredicates(p))
}
